 //var START = 0;\n  //var TOKEN_READ = 1;\n  //var STACKS_GROWN_1 = 2;\n  //var STACKS_GROWN_2 = 3;\n  //var SEMANTIC_ACTION_COMPUTED = 4;\n  //var ERROR_DETECTED = 5;\n  var loop = 6;\n  var testshift = 7;\n  var shift = 8;\n  var shift_recover = 9;\n  var reduce = 10;\n\n  var READ_TOKEN = 0;\n  var RAISE_PARSE_ERROR = 1;\n  var GROW_STACKS_1 = 2;\n  var GROW_STACKS_2 = 3;\n  var COMPUTE_SEMANTIC_ACTION = 4;\n  var CALL_ERROR_FUNCTION = 5;\n\n  var env_s_stack = 1;\n  var env_v_stack = 2;\n  var env_symb_start_stack = 3;\n  var env_symb_end_stack = 4;\n  var env_stacksize = 5;\n  var env_stackbase = 6;\n  var env_curr_char = 7;\n  var env_lval = 8;\n  var env_symb_start = 9;\n  var env_symb_end = 10;\n  var env_asp = 11;\n  var env_rule_len = 12;\n  var env_rule_number = 13;\n  var env_sp = 14;\n  var env_state = 15;\n  var env_errflag = 16;\n\n  // var _tbl_actions = 1;\n  var tbl_transl_const = 2;\n  var tbl_transl_block = 3;\n  var tbl_lhs = 4;\n  var tbl_len = 5;\n  var tbl_defred = 6;\n  var tbl_dgoto = 7;\n  var tbl_sindex = 8;\n  var tbl_rindex = 9;\n  var tbl_gindex = 10;\n  var tbl_tablesize = 11;\n  var tbl_table = 12;\n  var tbl_check = 13;\n  // var _tbl_error_function = 14;\n  var tbl_names_const = 15;\n  var tbl_names_block = 16;\n\n  function log(x) {\n    var s = caml_string_of_jsbytes(x + "\\n");\n    caml_ml_output(caml_ml_std_channel_id[2], s, 0, caml_ml_string_length(s));\n  }\n\n  function token_name(names, number) {\n    var str = caml_jsstring_of_string(names);\n    if (str[0] === "\\x00") return "<unknown token>";\n    return str.split("\\x00")[number];\n  }\n\n  function print_token(state, tok) {\n    var token, kind;\n    if (Array.isArray(tok)) {\n      token = token_name(tables[tbl_names_block], tok[0]);\n      if (typeof tok[1] === "number") kind = "" + tok[1];\n      else if (typeof tok[1] === "string") kind = tok[1];\n      else if (tok[1] instanceof MlBytes) kind = caml_jsbytes_of_string(tok[1]);\n      else kind = "_";\n      log("State " + state + ": read token " + token + "(" + kind + ")");\n    } else {\n      token = token_name(tables[tbl_names_const], tok);\n      log("State " + state + ": read token " + token);\n    }\n  }\n\n  if (!tables.dgoto) {\n    tables.defred = caml_lex_array(tables[tbl_defred]);\n    tables.sindex = caml_lex_array(tables[tbl_sindex]);\n    tables.check = caml_lex_array(tables[tbl_check]);\n    tables.rindex = caml_lex_array(tables[tbl_rindex]);\n    tables.table = caml_lex_array(tables[tbl_table]);\n    tables.len = caml_lex_array(tables[tbl_len]);\n    tables.lhs = caml_lex_array(tables[tbl_lhs]);\n    tables.gindex = caml_lex_array(tables[tbl_gindex]);\n    tables.dgoto = caml_lex_array(tables[tbl_dgoto]);\n  }\n\n  var res = 0,\n    n,\n    n1,\n    n2,\n    state1;\n\n  // RESTORE\n  var sp = env[env_sp];\n  var state = env[env_state];\n  var errflag = env[env_errflag];\n\n  the_loop: for (;;) {\n    switch (cmd) {\n      // biome-ignore lint/suspicious/noFallthroughSwitchClause: falls through\n      case 0: //START:\n        state = 0;\n        errflag = 0;\n      // falls through\n\n      case 6: //loop:\n        n = tables.defred[state];\n        if (n !== 0) {\n          cmd = reduce;\n          continue the_loop;\n        }\n        if (env[env_curr_char] >= 0) {\n          cmd = testshift;\n          continue the_loop;\n        }\n        res = READ_TOKEN;\n        break the_loop;\n      /* The ML code calls the lexer and updates */\n      /* symb_start and symb_end */\n      // biome-ignore lint/suspicious/noFallthroughSwitchClause: falls through\n      case 1: //TOKEN_READ:\n        if (Array.isArray(arg)) {\n          env[env_curr_char] = tables[tbl_transl_block][arg[0] + 1];\n          env[env_lval] = arg[1];\n        } else {\n          env[env_curr_char] = tables[tbl_transl_const][arg + 1];\n          env[env_lval] = 0;\n        }\n        if (caml_parser_trace) print_token(state, arg);\n      // falls through\n\n      // biome-ignore lint/suspicious/noFallthroughSwitchClause: falls through\n      case 7: //testshift:\n        n1 = tables.sindex[state];\n        n2 = n1 + env[env_curr_char];\n        if (\n          n1 !== 0 &&\n          n2 >= 0 &&\n          n2 <= tables[tbl_tablesize] &&\n          tables.check[n2] === env[env_curr_char]\n        ) {\n          cmd = shift;\n          continue the_loop;\n        }\n        n1 = tables.rindex[state];\n        n2 = n1 + env[env_curr_char];\n        if (\n          n1 !== 0 &&\n          n2 >= 0 &&\n          n2 <= tables[tbl_tablesize] &&\n          tables.check[n2] === env[env_curr_char]\n        ) {\n          n = tables.table[n2];\n          cmd = reduce;\n          continue the_loop;\n        }\n        if (errflag <= 0) {\n          res = CALL_ERROR_FUNCTION;\n          break the_loop;\n        }\n      // falls through\n      /* The ML code calls the error function */\n      case 5: //ERROR_DETECTED:\n        if (errflag < 3) {\n          errflag = 3;\n          for (;;) {\n            state1 = env[env_s_stack][sp + 1];\n            n1 = tables.sindex[state1];\n            n2 = n1 + ERRCODE;\n            if (\n              n1 !== 0 &&\n              n2 >= 0 &&\n              n2 <= tables[tbl_tablesize] &&\n              tables.check[n2] === ERRCODE\n            ) {\n              if (caml_parser_trace) log("Recovering in state " + state1);\n              cmd = shift_recover;\n              continue the_loop;\n            } else {\n              if (caml_parser_trace) log("Discarding state " + state1);\n              if (sp <= env[env_stackbase]) {\n                if (caml_parser_trace) log("No more states to discard");\n                return RAISE_PARSE_ERROR;\n              }\n              /* The ML code raises Parse_error */\n              sp--;\n            }\n          }\n        } else {\n          if (env[env_curr_char] === 0)\n            return RAISE_PARSE_ERROR; /* The ML code raises Parse_error */\n          if (caml_parser_trace) log